import{_ as d,C as a,c as s,o as i,aa as n,G as o}from"./chunks/framework.Cn7WEiMX.js";const v=JSON.parse('{"title":"网页界面参数","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/Dynmap/setup/web-setup/web-ui-parameters.md","filePath":"wiki/Dynmap/setup/web-setup/web-ui-parameters.md"}'),p={name:"wiki/Dynmap/setup/web-setup/web-ui-parameters.md"};function l(r,e,u,m,h,b){const t=a("NolebaseGitContributors"),c=a("NolebaseGitChangelog");return i(),s("div",null,[e[0]||(e[0]=n('<h1 id="网页界面参数" tabindex="-1">网页界面参数 <a class="header-anchor" href="#网页界面参数" aria-label="Permalink to &quot;网页界面参数&quot;">​</a></h1> <p>用于打开网页界面的链接支持一些参数，可以用来覆盖默认参数。可以让网页地图自动翻到某个世界的地图，或者指定缩放大小，以及聚焦在指定世界的位置。</p> <p>参数以键值对的形式提供，每个参数都按如下格式出现：</p> <div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>属性=值</span></span></code></pre></div><p>基本的链接末尾会有一个英文问号 <code>?</code>，每个参数之间都由英文和号 <code>&amp;</code> 隔开。因此网页地图的默认网址为：</p> <div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://mygreatserver:8123/</span></span></code></pre></div><p>之后，让网页地图选择名为 <code>fred</code> 的世界，显示 <code>surface</code> 类型的地图，格式则为：</p> <div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://mygreatserver:8123/?worldname=fred&amp;mapname=surface</span></span></code></pre></div><p>如果你使用的是外置网页服务器，那么格式是一样的——只需在末尾加上 <code>?</code>，然后加上 <code>&amp;</code> 隔开的参数即可：</p> <div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://mycoolapacheserver.com/dynmap?worldname=fred&amp;mapname=surface</span></span></code></pre></div><p>可填入的参数如下：</p> <ul><li><code>worldname</code> - 指定选中世界的名称（不是标题）。不填则选中定义的首个世界（除非 <code>configuration.txt</code> 中设置了 <code>defaultworld</code>，那么显示这个设置对应的世界）。</li> <li><code>mapname</code> - 指定地图类型的名称（不是标题）。不填则选中定义的首个地图（除非 <code>configuration.txt</code> 中设置了 <code>defaultmap</code>，那么显示这个设置对应的地图）。</li> <li><code>zoom</code> - 指定缩放大小（<code>0</code> 为最小缩放）。不填则使用 <code>0</code>（除非 <code>configuration.txt</code> 中设置了 <code>defaultzoom</code>）。</li> <li><code>x</code> - 决定了地图界面（对应世界）聚焦的 X 轴坐标。不填则使用指定世界 <code>center</code> 设置的对应坐标（通常为 <code>0</code>）。</li> <li><code>y</code> - 决定了地图界面（对应世界）聚焦的 Y 轴坐标。不填则使用指定世界 <code>center</code> 设置的对应坐标（通常为 <code>0</code>）。</li> <li><code>z</code> - 决定了地图界面（对应世界）聚焦的 Z 轴坐标。不填则使用指定世界 <code>center</code> 设置的对应坐标（通常为 <code>0</code>）。</li> <li><code>nopanel</code> - 若存在且设置为 true，则隐藏侧边栏菜单。</li> <li><code>chatname</code> - 若存在且设置内容，则在聊天栏中以此作为发送者名称。若开启 <code>trustclientname</code> 则只会被内置网页服务器接受，除非在聊天组件中将 <code>allowurlname</code> 设置开启。仅 0.28 之后的版本支持。</li> <li><code>playername</code> - 若存在且设置为对应（在线或稍后在线）玩家的名称，则网页界面会尝试寻找并聚焦玩家的位置。</li> <li><code>hidechat</code> - 若存在且设置为 true，网页界面会禁用所有聊天输入输出组件（聊天气泡、输入框以及聊天栏本身）。</li> <li><code>nogui</code> - 若存在且设置为 true，网页界面会禁用所有控制方式、面板等内容，只展示地图本身。</li> <li><code>nocompass</code> - 若存在且设置为 true，则隐藏指南针组件（v2.2-alpha-1 后）</li></ul> ',20)),o(t),o(c)])}const _=d(p,[["render",l]]);export{v as __pageData,_ as default};
